algStore :算法仓平台 sdc:sdc平台 community-gateway:社区网关平台
Other:其它平台', `user_data` text, `rect_list` varchar(255) DEFAULT NULL COMMENT '识别框点位信息(目标框左上右下坐标点)', `rect_float_list` varchar(255) DEFAULT NULL COMMENT '识别框点位信息(左上右下坐标所占原图的比例值)', `alg_object_list` varchar(255) DEFAULT NULL COMMENT '算法模型返回原始结果,可能存在多个', `area_id` bigint DEFAULT NULL COMMENT '区域标识', `image_data` text, `attr_json` text DEFAULT NULL COMMENT '目标属性集合', `extend_1` varchar(255) DEFAULT NULL, `extend_2` varchar(255) DEFAULT NULL, `extend_3` varchar(255) DEFAULT NULL, `sequence` bigint NOT NULL AUTO_INCREMENT COMMENT '主键', `audit_status` int DEFAULT 1 COMMENT '审核状态 0-错误 1-正确', `exist_video` int DEFAULT 0 COMMENT '是否存在视频录像 0-不存在 1-存在', PRIMARY KEY (`sequence`) USING BTREE, KEY `t_event_id` (`id`) USING BTREE, KEY `t_type_area_time` (`time`,`event_type`,`area_id`) USING BTREE, KEY `t_type_camera_time` (`time`,`camera_id`,`event_type`) USING BTREE ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='事件表';

